.kicker { color: var(--accent); text-transform: uppercase; letter-spacing: 0.09em; font-size: clamp(11px, 1vw, 17px); }
h1 { margin: clamp(8px,1vw,14px) 0; font-size: clamp(30px, 4vw, 58px); line-height: 1.07; max-width: 90%; }
h2 { margin: 0 0 clamp(10px,1.4vw,16px); font-size: clamp(25px, 3.1vw, 46px); line-height: 1.1; }
p, li, td, th { font-size: clamp(14px, 1.2vw, 21px); line-height: 1.35; }
.muted { color: var(--muted); }
.grid-2 { display: grid; grid-template-columns: 1.25fr 1fr; gap: clamp(14px, 1.6vw, 24px); align-items: stretch; height: calc(100% - clamp(70px, 9vh, 110px)); }
.panel {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: clamp(12px, 1.2vw, 20px);
  padding: clamp(14px, 1.6vw, 24px);
