.metric { font-size: clamp(26px, 4.2vw, 62px); font-weight: 700; color: var(--accent-2); }
.small { font-size: clamp(12px, 0.95vw, 15px); }
.table { width: 100%; border-collapse: collapse; table-layout: fixed; }
