.table th { color: #b9daf2; font-weight: 600; }
.rank { width: 8%; color: var(--accent); font-weight: 700; }
.vol { color: var(--accent-2); font-weight: 600; }
.wow.up { color: #7cf29c; }
.wow.down { color: #ff9bb0; }
.chart-wrap { display: flex; align-items: flex-end; justify-content: space-between; gap: clamp(8px, 1vw, 14px); height: min(52vh, 420px); margin-top: clamp(8px,1vw,14px); }
.bar-col { flex: 1; min-width: 0; display: flex; flex-direction: column; align-items: center; gap: clamp(4px, .5vw, 8px); }
