.bar.alt { background: linear-gradient(180deg, #89f8b4 0%, #2cbf71 100%); }
.bar.gold { background: linear-gradient(180deg, #ffe08a 0%, #e3a62a 100%); }
.bar.gray { background: linear-gradient(180deg, #ced9e6 0%, #8da4be 100%); }
.bar-label { text-align: center; font-size: clamp(10px, .82vw, 13px); color: #c8dbeb; }
.bar-val { font-weight: 700; color: #f3fbff; font-size: clamp(11px, .94vw, 15px); }
.badge { display: inline-block; font-size: clamp(10px, .8vw, 13px); padding: clamp(4px, .45vw, 7px) clamp(8px, .8vw, 12px); border-radius: 999px; border: 1px solid var(--line); background: rgba(33, 75, 108, .5); }
.cards { display: grid; grid-template-columns: repeat(2, 1fr); gap: clamp(10px, 1vw, 14px); }
.card { background: var(--panel-2); border: 1px solid var(--line); border-radius: clamp(10px, .9vw, 14px); padding: clamp(10px, 1vw, 15px); }
ul { margin: 0; padding-left: clamp(18px, 1.8vw, 26px); }
li { margin-bottom: clamp(6px, .7vw, 10px); }
.footer { position: absolute; bottom: clamp(8px, 1vh, 16px); right: clamp(16px,1.8vw,28px); font-size: clamp(10px,.8vw,13px); color:#88aaca; }
@media (max-height: 700px) {
  .chart-wrap { height: min(46vh, 340px); }
}
@media (max-height: 600px) {
  h2 { font-size: clamp(20px, 2.2vw, 34px); }
  p, li, td, th { font-size: clamp(12px, 1vw, 16px); }
